def divisors(n):
    """Get all divisors of n greater than 1"""
    divs = []
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            divs.append(i)
            if i != n // i:
                divs.append(n // i)
    if n > 1:
        divs.append(n)
    return sorted(divs)

def gcd(a, b):
    return math.gcd(a, b)

def solution(input_str):
    lines = input_str.strip().split('\n')
    t = int(lines[0])

    results = []

    for i in range(1, t + 1):
        n = int(lines[i])
        divs = [d for d in divisors(n) if d > 1]

        # For composite number n, we need to find if we can arrange divisors
        # such that no adjacent pairs are coprime, otherwise we need moves

        # Key insight: For n = p * q (product of distinct primes), 
        # we have 4 divisors: p, q, pq, and 1 (but 1 is excluded).
        # So divisors are p, q, n.
        # p and q are coprime, so they cannot be adjacent without LCM insertion.
        # n = pq is divisible by both p and q.

        # If n has only 2 distinct prime factors, we need to handle it specially
        # If n is a prime power (p^k), all divisors share p, so gcd is at least p

        from sympy import primefactors  # Fallback if available
        try:
            import sympy
            distinct_primes = list(sympy.factorint(n).keys())
        except ImportError:
            distinct_primes = []
            temp = n
            seen = set()
            d = 2
            while d * d <= temp:
                if temp % d == 0:
                    seen.add(d)
                    while temp % d == 0:
                        temp //= d
                d += 1
            if temp > 1:
                seen.add(temp)
            distinct_primes = list(seen)

        # Count distinct prime factors
        num_prime_factors = len(distinct_primes)

        # For numbers with more than 1 distinct prime factor, we might need moves
        # Special case: if all divisors share a common prime, 0 moves needed

        # Find GCD of all divisors (for their structure)
        common_prime = None
        for p in distinct_primes:
            # Check if all divisors are divisible by p
            all_divisible = all(d % p == 0 for d in divs)
            if all_divisible:
                common_prime = p
                break

        # If there's a prime dividing all divisors, we can arrange in 0 moves
        if common_prime:
            results.append(" ".join(map(str, divs)))
            results.append("0")
            continue

        # Check if n is a product of exactly 2 primes (and no higher powers make it composite of one)
        # For n = p*q, divisors are p, q, pq -> p and q coprime, need 1 move

        # Try to arrange divisors and see if any arrangement works with 0 moves
