                        break
                # Check wrap-around
                if ok and gcd(perm[-1], perm[0]) == 1:
                    ok = False
                if ok:
                    min_moves = 0
                    best_order = perm
                    break

            if best_order:
                results.append(" ".join(map(str, best_order)))
                results.append("0")
            else:
                results.append(" ".join(map(str, divs)))
                results.append("1")
        elif num_prime_factors == 1:
            results.append(" ".join(map(str, divs)))
            results.append("0")
        elif num_prime_factors == 2 and n < 100:
            from itertools import permutations
            min_moves = 2
            best_order = None
            for perm in permutations(divs):
