        # Check axis-aligned squares
        for size in range(2, min(n, m) + 1):
            for r in range(n - size + 1):
                for c in range(m - size + 1):
                    if check_axis_square(matrix, r, c, size, n, m):
                        count += 1

        # Check diagonal squares
        for size in range(2, min(n, m) + 1):
            for r in range(n - size + 1):
                for c in range(m - size + 1):
                    if check_diagonal_square(matrix, r, c, size, n, m):
                        count += 1

        results.append(str(count))

    return '\n'.join(results)


def check_axis_square(matrix, r, c, size, n, m):
    """Check if there's an axis-aligned square at (r,c) with given size."""
    if size < 2 or r + size > n or c + size > m:
        return False

    # Check top row (must be all 1s)
    if not all(matrix[r][c + i] == 1 for i in range(size)):
        return False
    # Check bottom row (must be all 1s)
    if not all(matrix[r + size - 1][c + i] == 1 for i in range(size)):
        return False
    # Check left column (must be all 1s)
    if not all(matrix[r + i][c] == 1 for i in range(size)):
        return False
    # Check right column (must be all 1s)
    if not all(matrix[r + i][c + size - 1] == 1 for i in range(size)):
        return False

    # Check all neighbors of border cells are 0 (can't touch foreign 1s)
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            for i in range(size):
                # Top row neighbors
                nr, nc = r + dr, c + i + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if matrix[nr][nc] == 1:
                        return False
                # Bottom row neighbors
                nr, nc = r + size - 1 + dr, c + i + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if matrix[nr][nc] == 1:
                        return False
                # Left column neighbors
                nr, nc = r + i + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if matrix[nr][nc] == 1:
                        return False
                # Right column neighbors
                nr, nc = r + i + dr, c + size - 1 + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if matrix[nr][nc] == 1:
                        return False

    return True


def check_diagonal_square(matrix, r, c, size, n, m):
    """Check if there's a diagonal square at (r,c) with given size."""
    if size < 2 or r + size > n or c + size > m:
        return False

    # For a diagonal square of side 'size', check the diamond border
    # Top, right, bottom, left points
    if matrix[r][c] != 1:
        return False
    if matrix[r + size - 1][c + size - 1] != 1:
        return False
    if matrix[r + size - 1][c] != 1:
        return False
    if matrix[r][c + size - 1] != 1:
        return False

    # Check sides of the diamond (exclude corners to avoid double counting)
    for i in range(1, size - 1):
        if matrix[r][c + size - 1 - i] == 0:  # Top side
            return False
        if matrix[r + size - 1 - i][c + i] == 0:  # Right side
            return False
        if matrix[r + size - 1][c + i] == 0:  # Bottom side
            return False
        if matrix[r + i][c + size - 1 - i] == 0:  # Left side
            return False

    # Check all neighbors of border cells are 0
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            # Check neighbors around top, right, bottom, left sides
            for i in range(size):
                if i == 0 or i == size - 1:
                    continue  # Skip corners (checked above with size limit)
                # Top side neighbors
                nr, nc = r + dr, c + size - 1 - i + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if matrix[nr][nc] == 1:
                        return False
                # Right side neighbors
                nr, nc = r + size - 1 - i + dr, c + i + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if matrix[nr][nc] == 1:
                        return False
                # Bottom side neighbors
                nr, nc = r + size - 1 + dr, c + i + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if matrix[nr][nc] == 1:
                        return False
                # Left side neighbors
                nr, nc = r + i + dr, c + size - 1 - i + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if matrix[nr][nc] == 1:
                        return False

    return True
