    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(n + 1):
        for j in range(m + 1):
            if dp[i][j] == 0:
                continue

            if k + i - j >= 0:
                # Try adding next 10-euro person
                if i < n:
                    dp[i + 1][j] += dp[i][j]

                # Try adding next 20-euro person
                if j < m and k + i - (j + 1) >= 0:
                    dp[i][j + 1] += dp[i][j]

    valid_count = dp[n][m]

    # Total = C(n+m, n)
    def comb(n, k):
        result = 1
        for i in range(k):
            result = result * (n - i) // (i + 1)
        return result

    total_count = comb(n + m, n)

    prob = valid_count / total_count if total_count > 0 else 0.0
