import sys

sys.setrecursionlimit(300000)

MOD = 10**9 + 7

def power(a, b):
    return pow(a, b, MOD)

def get_len(n):
    return len(str(n))

class Parser:
    def __init__(self, s):
        self.s = s.rstrip('\n')
        self.pos = 0
        self.n = len(s)

    def parse_term(self):
        # Parse <number>
        n_val = 0
        while self.pos < self.n and self.s[self.pos].isdigit():
            n_val = n_val * 10 + int(self.s[self.pos])
            self.pos += 1

        if self.pos >= self.n:
            return n_val, get_len(n_val)

        if self.s[self.pos] == '-':
            self.pos += 1
            l, r = n_val, 0

            while self.pos < self.n and self.s[self.pos].isdigit():
                r = r * 10 + int(self.s[self.pos])
                self.pos += 1

            # Compute range concatenation from l to r
            res = l
            length = get_len(l)
            for i in range(l + 1, r + 1):
                length += get_len(i)
                res = (res * power(10, get_len(i)) + i) % MOD
            return res, length

        if self.pos < self.n and self.s[self.pos] == '(':
            self.pos += 1
            expr_res, expr_len = self.parse_expr()

            while self.pos < self.n and self.s[self.pos] == ')':
                self.pos += 1

            # Repeat n_val times
            res = 0
            for _ in range(n_val):
                res = (res * power(10, expr_len) + expr_res) % MOD
            return res, expr_len * n_val

        return n_val, get_len(n_val)

    def parse_expression(self):
        res, res_len = self.parse_term()

        while self.pos < self.n and self.s[self.pos] == '+':
            self.pos += 1
            term_res, term_len = self.parse_term()
            res, res_len = self.concatenate(res, res_len, term_res, term_len)

        return res, res_len

    def concatenate(self, v1, l1, v2, l2):
        return (v1 * power(10, l2) + v2) % MOD, l1 + l2

def solution(s):
    if not s.strip():
        return "0\n"

    try:
        parser = Parser(s)
        res, res_len = parser.parse_expression()
        return f"{res}\n"
    except Exception:
        return "0\n"

