        all_can_A = all(can_in_A.get(val, False) for val in component if val in can_in_A)

        # Check if it can all go to B
        all_can_B = all(can_in_B.get(val, False) for val in component if val in can_in_B)

        if all_can_A and all_can_B:
            # Can go to either, choose A for simplicity
            for val in component:
