        a = dist(p1, p2)
        b = dist(p2, p3)
        c = dist(p3, p1)
        s = (a + b + c) / 2
        if s <= 0 or s - a <= 0 or s - b <= 0 or s - c <= 0:
            return float('inf')
        area_sq = s * (s - a) * (s - b) * (s - c)
        if area_sq <= 1e-12:
            return float('inf')
        area = area_sq**0.5
        return (a * b * c) / (4 * area)

