    except:
        return "0\n..")

    if n <= 0 or m <= 0:
        return "0\n" + "\n".join(["." * m] * n)

    # Four T-shape orientations
    shapes = [
        [(0,0),(0,1),(0,2),(1,1)],
        [(0,1),(1,0),(1,1),(1,2)],
        [(1,0),(1,1),(1,2),(0,1)],
        [(0,1),(1,1),(2,1),(1,0)]
    ]

    best_cnt = [0]
    best_grid = [["." for _ in range(m)] for _ in range(n)]

    def can_place(shape, r, c, g):
        for dr, dc in shape:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < n and 0 <= nc < m) or g[nr][nc] != '.':
                return False
        return True

    def solve(idx, cnt, g):
        nonlocal best_cnt, best_grid
        if idx == n * m:
            if cnt > best_cnt[0]:
                best_cnt[0] = cnt
                best_grid = [row[:] for row in g]
            return

        r, c = idx // m, idx % m

        # Skip
        solve(idx + 1, cnt, g)

        # Try each shape
        for i, shape in enumerate(shapes):
            if can_place(shape, r, c, g):
                for dr, dc in shape:
                    g[r + dr][c + dc] = chr(ord('A') + i)
                solve(idx + 1, cnt + 1, g)
                for dr, dc in shape:
                    g[r + dr][c + dc] = '.'

    solve(0, 0, [["." for _ in range(m)] for _ in range(n)])

    return f"{best_cnt[0]}\n" + "\n".join(''.join(row) for row in best_grid) + "\n"
