import sys
from collections import deque, defaultdict

def get_path_vertices(adj, start, end):
    """Get all vertices on the simple path between start and end."""
    parent = {start: None}
    queue = deque([start])

    while queue:
        u = queue.popleft()
        if u == end:
            break
        for v in adj[u]:
            if v not in parent:
                parent[v] = u
                queue.append(v)

    if end not in parent:
        return set()

    path = []
    curr = end
    while curr is not None:
        path.append(curr)
        curr = parent[curr]

    return set(path)

def bfs_distance(adj, start):
    """Return distance array from start to all vertices."""
    dist = [-1] * (len(adj) + 1)
    dist[start] = 0
    queue = deque([start])

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == -1:
