```python
def solution(input_str):
    data = input_str.strip().split('\n')
    if not data:
        return "-1"

    n = int(data[0])

    # Parse adjacency matrix: adj[i][j] = 1 if employee i sends to employee j
    adj = []
    for i in range(n):
        row = data[i + 1]
        adj.append([int(c) for c in row])

    predictions = list(map(int, data[n + 1].split()))

    # Try all subsets using recursion with backtracking
    def search(idx, mask, counts):
        if idx == n:
            # Check if all actual counts differ from predictions
            if all(counts[i] != predictions[i] for i in range(n)):
                return mask
            return None

        # Option 1: Include employee idx
        new_mask = mask | (1 << idx)
        new_counts = list(counts)
        for j in range(n):
            if adj[idx][j]:
                new_counts[j] += 1

        result = search(idx + 1, new_mask, new_counts)
        if result is not None:
            return result

        # Option 2: Exclude employee idx
        return search(idx + 1, mask, counts)

    result_mask = search(0, 0, [0] * n)

    if result_mask is None:
        return "-1"

    # Convert mask to list of employee numbers (1-indexed, in any order)
    result_employees = [i + 1 for i in range(n) if (result_mask >> i) & 1]

    output = f"{len(result_employees)}\n{' '.join(map(str, result_employees))}\n"
    return output
